MATCH (tank:Tank {tag: "T-6001"})-[:send_to]-(valve:PlantItem)
MATCH (controller:ProcessControlFunction)-[:send_signal_to]->(:ActuatingFunction)-[:control]->(valve)
RETURN DISTINCT controller.loop_tag AS loop_tag;

MATCH (s:PlantItem {tag: 'P-5902'})-[:send_to*1..]->(v:PlantItem {tag: 'V-6001'})
RETURN DISTINCT s.tag AS source_tag, v.tag AS target_tag
LIMIT 1;

MATCH (s:PlantItem {tag: 'P-4501B'}), (e:PlantItem {tag: 'EA-4601'})
RETURN s.tag AS from_tag, e.tag AS to_tag,
       EXISTS { MATCH (s)-[:send_to*1..]->(e) } AS can_reach;

MATCH (v:PlantItem)-[:send_to*1..]->(:PlantItem {tag: 'E-3702'})
WHERE any(label IN labels(v) WHERE label IN [
  'GateValve', 'BallValve', 'AngleBallValve', 'GlobeValve',
  'AngleGlobeValve', 'AngleValve', 'PlugValve', 'AnglePlugValve',
  'ButterflyValve', 'NeedleValve', 'StraightwayValve'
])
AND NOT EXISTS { MATCH (:PlantItem)-[:control]->(v) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem)-[:send_to*1..]->(:PlantItem {tag: 'P-101A'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag;

MATCH (target:PlantItem {tag: 'E-401'})
MATCH (source:PlantItem)-[:send_to*1..]->(target)
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag

MATCH (source:PlantItem {tag: 'E-3502'}),
